/* The Super Rare hunts (.plan/tasks/super-rare-hunts.md; the owner's design of 2026-11-17).
 *
 * Twelve hunts in order (def_super_rares, generated by tools/gen_hunt_targets.py): the next one opens when the one before
 * is finished, and a finished one can be repeated. One is active at a time; cancelling it heals the target. The target
 * sits on a map with random encounters of its territory (a sector of one server), drawn at random each time it moves,
 * so two hunts never walk the same way. The compass reads the distance in maps (the exits' graph,
 * definitive_map_graph.c) and, on the target's map, the distance to its point: of the candidate points the field gives
 * (definitive_superhunt_field.c: tiles where random encounters happen, so walkable), the one farthest from where the
 * player came in. Stepping on it starts the battle: the target alone, at its level, with the HP it has left and
 * DEF_SUPER_BUFF_PCT more stats for each battle before. Once it has lost DEF_SUPER_FLEE_PCT of its full HP in a battle it
 * flees, and so after a battle it did not lose (the party fled or fell) it moves to another map. Won: its crystal.
 *
 * Pure logic, but for pad_random and the map-to-region table: the host test (tests/port/definitive_superhunt.py) builds
 * it alone. Off in a replay script (def_on): nothing changes and nothing is drawn. */
#include <string.h>

#include "common.h"
#include "pad.h"
#include "records.h"

#include "psxstack/savestate.h"

#include "definitive.h"

extern unsigned char ststatus_map_areas[];
extern int def_on(void);
extern void port_log(const char *fmt, ...);

static struct {
    signed char active;  /* the hunt under way, -1: none */
    unsigned char done;  /* hunts finished in order: hunt `done` is the next to open */
    unsigned short map;  /* the target's map */
    unsigned short lost; /* the HP it has lost */
    unsigned char meets; /* battles it has been in this hunt (its buff) */
    unsigned char flags; /* DEF_SUPER_FLAG_*: the Velvet Room's first visit, the tutorial given */
    unsigned char crystals[DEF_SUPER_COUNT];
} st = { -1, 0, 0, 0, 0, 0, { 0 } };

/* The target's point on its map, and the battle being fought (neither is saved: the point is taken again at the first
 * step on the map after a load, a battle is never saved in the middle). The point stays while the target stays. */
static struct {
    signed char set;      /* a point was taken */
    short px, py;         /* the point */
    short range;          /* farthest candidate distance from the point (for the precision thermometer) */
    signed char battle;   /* the battle being set up or fought is the Super Rare's */
    short hp_start;       /* its HP when the battle began, in the battle's units */
    short hp_max;         /* its full HP in the battle's units (Super Hard raises it: def_super_hp) */
    signed char won;      /* a hunt just won + 1, for the field's panel (def_super_won_take); 0: none */
    signed char first;    /* that win was the hunt's first: it raised done, so it unlocked a skin */
    signed char blasted;  /* a Blast was set off in the tutorial battle: the target stays to the end */
    signed char fled_who; /* why this battle is ending in escape (DEF_SUPER_FLED_*) */
    signed char fled;     /* pending escape notice for the field (def_super_fled_take) */
} run;

/* ---- The map graph. */

int def_map_node(int map) {
    int lo = 0, hi = def_map_node_count - 1;

    while (lo <= hi) { /* def_map_nodes is sorted */
        int mid = (lo + hi) / 2;

        if (def_map_nodes[mid] == map) {
            return mid;
        }
        if (def_map_nodes[mid] < map) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int def_map_distance(int from, int to) {
    static short dist[512];
    static unsigned short queue[512];
    int a = def_map_node(from), b = def_map_node(to), head = 0, tail = 0, i;

    if (a < 0 || b < 0 || def_map_node_count > 512) {
        return -1;
    }
    for (i = 0; i < def_map_node_count; i++) {
        dist[i] = -1;
    }
    dist[a] = 0;
    queue[tail++] = (unsigned short)a;
    while (head < tail) {
        int n = queue[head++];

        if (n == b) {
            return dist[n];
        }
        for (i = def_map_first[n]; i < def_map_first[n + 1]; i++) {
            int m = def_map_edges[i];

            if (dist[m] < 0) {
                dist[m] = (short)(dist[n] + 1);
                queue[tail++] = (unsigned short)m;
            }
        }
    }
    return -1;
}

/* ---- Territories. */

/* The territory (sector * 2 + server) of map `map`, -1: none (the vehicles' maps, Duel Island, the towns' interiors
 * past 0x2FF, which share ststatus_map_areas's bytes with the fields). */
static int territory_of(int map) {
    int region, area;

    if (map < 0x200 || map >= 0x300) {
        return -1;
    }
    region = ststatus_map_areas[map & 0xFF];
    area = region & 0x7F;
    if (region == 0xFF || area >= DEF_HUNT_AREAS || def_hunt_sector_of[area] < 0) {
        return -1;
    }
    return def_hunt_sector_of[area] * 2 + (region >> 7);
}

static int territory_of_hunt(int hunt) {
    return def_super_rares[hunt].sector * 2 + def_super_rares[hunt].server;
}

/* Region (a ststatus_map_areas byte) `region` is hunt `hunt`'s ground: its territory, or its one area (the tutorial's). */
static int hunt_region(int hunt, int region) {
    const DefSuperRare *t = &def_super_rares[hunt];
    int area = region & 0x7F;

    if (region == 0xFF || area >= DEF_HUNT_AREAS) {
        return 0;
    }
    if (t->area >= 0) {
        return area == t->area && (region >> 7) == t->server;
    }
    return def_hunt_sector_of[area] >= 0 && def_hunt_sector_of[area] * 2 + (region >> 7) == territory_of_hunt(hunt);
}

static int hunt_map(int hunt, int map) {
    return map >= 0x200 && map < 0x300 && territory_of(map) >= 0 && hunt_region(hunt, ststatus_map_areas[map & 0xFF]);
}

int def_super_in_territory(int map) {
    return st.active >= 0 && hunt_map(st.active, map);
}

/* The steps (exits) from `map` to the nearest map of hunt `hunt`'s territory, -1: none reachable. A breadth-first walk
 * that stops at the first territory map; kept for the last map and hunt asked, as the compass asks every frame. */
int def_super_territory_distance(int hunt, int map) {
    static int last_hunt = -1, last_map = -1, last_d = -1;
    static short dist[512];
    static unsigned short queue[512];
    int a, head = 0, tail = 0, i;

    if (hunt < 0 || hunt >= DEF_SUPER_COUNT) {
        return -1;
    }
    if (hunt == last_hunt && map == last_map) {
        return last_d;
    }
    last_hunt = hunt;
    last_map = map;
    last_d = -1;
    a = def_map_node(map);
    if (a < 0 || def_map_node_count > 512) {
        return -1;
    }
    for (i = 0; i < def_map_node_count; i++) {
        dist[i] = -1;
    }
    dist[a] = 0;
    queue[tail++] = (unsigned short)a;
    while (head < tail) {
        int n = queue[head++];

        if (hunt_map(hunt, def_map_nodes[n])) {
            return last_d = dist[n];
        }
        for (i = def_map_first[n]; i < def_map_first[n + 1]; i++) {
            int m = def_map_edges[i];

            if (dist[m] < 0) {
                dist[m] = (short)(dist[n] + 1);
                queue[tail++] = (unsigned short)m;
            }
        }
    }
    return -1;
}

/* The compass shows on the territory and on the maps up to DEF_SUPER_COMPASS_REACH exits out of it, so it leads the
 * player in from the towns and fields around (the tutorial's territory is Central Park alone). */
int def_super_in_compass_zone(int map) {
    int d;

    return st.active >= 0 && (d = def_super_territory_distance(st.active, map)) >= 0 && d <= DEF_SUPER_COMPASS_REACH;
}

int def_super_in_region(int region) {
    return st.active >= 0 && hunt_region(st.active, region);
}

/* A map of the hunt's territory with random encounters, drawn at random, other than `not1` and `not2` (where it was,
 * where the player is) when there is another. */
static int draw_map(int hunt, int not1, int not2) {
    int i, n = 0, pick, any = 0;

    for (i = 0; i < def_map_node_count; i++) {
        int m = def_map_nodes[i];

        if (def_map_wild[i] && hunt_map(hunt, m)) {
            any = m;
            n += m != not1 && m != not2;
        }
    }
    if (n == 0) {
        return any;
    }
    pick = (int)((pad_random.next() & 0x7FFF) % n);
    for (i = 0; i < def_map_node_count; i++) {
        int m = def_map_nodes[i];

        if (def_map_wild[i] && hunt_map(hunt, m) && m != not1 && m != not2 && pick-- == 0) {
            return m;
        }
    }
    return any;
}

/* ---- The hunts. */

int def_super_active(void) {
    return st.active;
}

int def_super_done(void) {
    return st.done;
}

int def_super_state(int hunt) {
    if (hunt < 0 || hunt >= DEF_SUPER_COUNT) {
        return DEF_SUPER_LOCKED;
    }
    if (hunt == st.active) {
        return DEF_SUPER_ACTIVE;
    }
    return hunt < st.done ? DEF_SUPER_DONE : hunt == st.done ? DEF_SUPER_OPEN : DEF_SUPER_LOCKED;
}

int def_super_start(int hunt) {
    int s = def_super_state(hunt);

    if (!def_on() || st.active >= 0 || (s != DEF_SUPER_OPEN && s != DEF_SUPER_DONE)) {
        return 0;
    }
    st.active = (signed char)hunt;
    st.lost = 0;
    st.meets = 0;
    st.map = (unsigned short)draw_map(hunt, -1, -1);
    run.set = 0;
    run.fled_who = 0;
    run.fled = 0;
    port_log("super: hunt %d started, the target on map 0x%X", hunt, st.map);
    return 1;
}

void def_super_cancel(void) {
    if (st.active >= 0) {
        port_log("super: hunt %d cancelled", st.active);
    }
    st.active = -1;
    st.map = 0;
    st.lost = 0;
    st.meets = 0;
    run.set = 0;
    run.fled_who = 0;
    run.fled = 0;
}

int def_super_map(void) {
    return st.active >= 0 ? st.map : 0;
}

int def_super_hp_left(void) {
    return st.active >= 0 ? def_super_rares[st.active].hp - st.lost : 0;
}

int def_super_meets(void) {
    return st.meets;
}

int def_super_crystals(int hunt) {
    return hunt >= 0 && hunt < DEF_SUPER_COUNT ? st.crystals[hunt] : 0;
}

int def_super_won_take(int *first) {
    int hunt = run.won - 1;

    *first = run.first;
    run.won = 0;
    run.first = 0;
    return hunt;
}

int def_super_flags(void) {
    return st.flags;
}

void def_super_flag_set(int flag) {
    st.flags |= (unsigned char)flag;
}

/* One crystal of hunt `hunt` sold: its price (0: none held). The caller pays it. */
int def_super_crystal_sell(int hunt) {
    if (hunt < 0 || hunt >= DEF_SUPER_COUNT || st.crystals[hunt] == 0) {
        return 0;
    }
    st.crystals[hunt]--;
    port_log("super: a crystal of hunt %d sold for %d Bits (%d left)", hunt, def_super_rares[hunt].price,
             st.crystals[hunt]);
    return def_super_rares[hunt].price;
}

void def_super_crystal_add(int hunt, int n) {
    int v;

    if (hunt < 0 || hunt >= DEF_SUPER_COUNT) {
        return;
    }
    v = st.crystals[hunt] + n;
    st.crystals[hunt] = (unsigned char)(v < 0 ? 0 : v > DEF_SUPER_CRYSTAL_CAP ? DEF_SUPER_CRYSTAL_CAP : v);
}

/* ---- The compass and the point. */

static int dist2(int x0, int y0, int x1, int y1) {
    return (x1 - x0) * (x1 - x0) + (y1 - y0) * (y1 - y0);
}

static int isqrt_i(int n) {
    int x, nx;

    if (n <= 0) {
        return 0;
    }
    x = n;
    while (1) {
        nx = (x + n / x) >> 1;
        if (nx >= x) {
            return x;
        }
        x = nx;
    }
}

void def_super_set_points(const short *xy, int count, int x, int y) {
    static short order[DEF_SUPER_POINTS_MAX];
    static int dist[DEF_SUPER_POINTS_MAX];
    int i, j, max_d2 = 0, max_d;

    if (count > DEF_SUPER_POINTS_MAX) {
        count = DEF_SUPER_POINTS_MAX;
    }
    run.set = 1;
    if (count <= 0) {
        run.px = (short)x; /* no candidate (a map without encounter tiles): it is found where the player stands */
        run.py = (short)y;
        run.range = 240;
        return;
    }
    /* By distance from where the player came in (an insertion sort: a few hundred candidates, once per placement); the
     * one two thirds of the way: far enough to look for, never the farthest corner (the owner: "careful not to put it
     * in an impossible corner"). */
    for (i = 0; i < count; i++) {
        int d = dist2(x, y, xy[2 * i], xy[2 * i + 1]);

        for (j = i; j > 0 && dist[j - 1] > d; j--) {
            dist[j] = dist[j - 1];
            order[j] = order[j - 1];
        }
        dist[j] = d;
        order[j] = (short)i;
    }
    i = order[count * 2 / 3];
    run.px = xy[2 * i];
    run.py = xy[2 * i + 1];
    for (i = 0; i < count; i++) {
        int d = dist2(run.px, run.py, xy[2 * i], xy[2 * i + 1]);

        if (d > max_d2) {
            max_d2 = d;
        }
    }
    max_d = isqrt_i(max_d2);
    run.range = (short)(max_d < 240 ? 240 : max_d);
}

int def_super_temperature(int map, int x, int y) {
    int d;

    if (!def_super_in_compass_zone(map)) {
        return DEF_TEMP_NONE;
    }
    if (map == st.map) {
        if (!run.set) {
            return DEF_TEMP_HOT;
        }
        return dist2(x, y, run.px, run.py) <= 120 * 120 ? DEF_TEMP_BURNING : DEF_TEMP_HOT;
    }
    d = def_map_distance(map, st.map);
    return d == 1 ? DEF_TEMP_WARM : d >= 2 && d <= 3 ? DEF_TEMP_COOL : DEF_TEMP_COLD;
}

int def_super_proximity(int map, int x, int y) {
    int d, r, p;

    if (!def_super_in_compass_zone(map) || map != st.map || !run.set) {
        return -1;
    }
    d = isqrt_i(dist2(x, y, run.px, run.py));
    if (d <= DEF_SUPER_POINT_RADIUS) {
        return 100;
    }
    r = run.range > 240 ? run.range : 240;
    if (d >= r) {
        return 0;
    }
    if (r <= 160) {
        p = 100 * (r - d) / (r - DEF_SUPER_POINT_RADIUS);
    } else if (d <= 160) {
        p = 60 + 39 * (160 - d) / (160 - DEF_SUPER_POINT_RADIUS);
    } else {
        p = 60 * (r - d) / (r - 160);
    }
    return p < 0 ? 0 : p > 100 ? 100 : p;
}

int def_super_step(int map, int x, int y) {
    if (!def_on() || st.active < 0 || map != st.map) {
        return 0;
    }
    if (!run.set) {
        return 2; /* the field gives the candidate points (def_super_set_points), then asks again */
    }
    if (dist2(x, y, run.px, run.py) > DEF_SUPER_POINT_RADIUS * DEF_SUPER_POINT_RADIUS) {
        return 0;
    }
    run.battle = 1;
    run.blasted = 0;
    port_log("super: hunt %d, the target found on map 0x%X (HP %d left, battle %d)", st.active, map, def_super_hp_left(),
             st.meets + 1);
    return 1;
}

/* ---- The battle. */

int def_super_battle(void) {
    return st.active >= 0 ? def_super_rares[st.active].battle : -1;
}

int def_super_battle_ready(void) {
    return run.battle && st.active >= 0;
}

void def_super_scale(void) {
    const DefSuperRare *t;
    RecordsEnemy e;
    int i;

    if (!def_super_battle_ready()) {
        return;
    }
    t = &def_super_rares[st.active];
    e = records_state.enemies[t->slot];
    for (i = 0; i < 3; i++) {
        memset(&records_state.enemies[i], 0, sizeof(records_state.enemies[i]));
    }
    e.level = t->level;
    e.hp = t->hp; /* its full HP: the battle's HP bar; the HP left is the battle side's (def_super_hp_left) */
    e.stat_scale = (short)(e.stat_scale * (100 + DEF_SUPER_BUFF_PCT * st.meets) / 100);
    records_state.enemies[0] = e;
    run.hp_max = t->hp;
    run.hp_start = (short)def_super_hp_left();
}

int def_super_hp_start(int max_hp) {
    if (!def_super_battle_ready() || max_hp <= 0) {
        return max_hp;
    }
    run.hp_max = (short)max_hp;
    run.hp_start = (short)((long)max_hp * def_super_hp_left() / def_super_rares[st.active].hp);
    if (run.hp_start < 1) {
        run.hp_start = 1;
    }
    return run.hp_start;
}

int def_super_tutorial_battle(void) {
    return def_super_battle_ready() && st.active == DEF_SUPER_TUTORIAL;
}

void def_super_blast_note(void) {
    if (def_super_battle_ready()) {
        run.blasted = 1;
        port_log("super: the blessed Blast is up: the target will not flee");
    }
}

/* The player's hit on a Super Rare: its share (DEF_SUPER_DAMAGE_PCT), never to nothing. The tutorial's hits are whole. */
int def_super_damage(int side, int damage) {
    if (side != 0 || damage <= 0 || !def_super_battle_ready() || st.active == DEF_SUPER_TUTORIAL || !def_on()) {
        return damage;
    }
    damage = damage * DEF_SUPER_DAMAGE_PCT / 100;
    return damage < 1 ? 1 : damage;
}

int def_super_should_flee(int hp_now) {
    if (!def_super_battle_ready() || hp_now <= 0 || run.blasted) {
        return 0;
    }
    return (run.hp_start - hp_now) * 100 >= run.hp_max * DEF_SUPER_FLEE_PCT;
}

void def_super_flee_note(int who) {
    if (def_super_battle_ready()) {
        run.fled_who = (signed char)who;
    }
}

int def_super_fled_take(void) {
    int who = run.fled;

    run.fled = 0;
    return who;
}

void def_super_battle_end(int result, int hp) {
    int hunt = st.active;

    if (!run.battle || hunt < 0) {
        run.battle = 0;
        run.fled_who = 0;
        return;
    }
    run.battle = 0;
    run.set = 0;
    if (result == 1 || hp <= 0) {
        run.fled_who = 0;
        run.fled = 0;
        def_super_crystal_add(hunt, def_hunt_mark_mult(1)); /* the Hunter's Mark: double */
        run.first = hunt == st.done && st.done < DEF_SUPER_COUNT;
        if (run.first) {
            st.done++;
        }
        port_log("super: hunt %d won, crystal %d", hunt, st.crystals[hunt]);
        def_super_cancel();
        run.won = (signed char)(hunt + 1);
        return;
    }
    if (result == 0) {
        run.fled = (signed char)(run.fled_who ? run.fled_who : DEF_SUPER_FLED_TARGET);
    } else {
        run.fled = 0;
    }
    run.fled_who = 0;
    /* its HP back in the table's units */
    hp = run.hp_max > 0 ? (int)((long)hp * def_super_rares[hunt].hp / run.hp_max) : hp;
    st.lost = (unsigned short)(def_super_rares[hunt].hp - (hp < 1 ? 1 : hp));
    if (st.meets < DEF_SUPER_MEETS_CAP) {
        st.meets++;
    }
    st.map = (unsigned short)draw_map(hunt, st.map, -1);
    port_log("super: hunt %d, %s to map 0x%X (HP %d left, meets %d)", hunt,
             run.fled == DEF_SUPER_FLED_PLAYER ? "the player fled" : "the target fled", st.map, hp, st.meets);
}

/* ---- The save: DEF_SUPER_RECORD bytes, all zero with nothing to keep. [0] the active hunt + 1, [1] done, [2..3] the
 * map, [4..5] the HP lost, [6] the battles, [7] the flags, [8..20] the crystals, the rest unused. */

int def_super_record_empty(void) {
    int i;

    for (i = 0; i < DEF_SUPER_COUNT && st.crystals[i] == 0; i++) {
    }
    return st.active < 0 && st.done == 0 && st.flags == 0 && i == DEF_SUPER_COUNT;
}

void def_super_record_write(unsigned char *out) {
    memset(out, 0, DEF_SUPER_RECORD);
    out[0] = (unsigned char)(st.active + 1);
    out[1] = st.done;
    out[2] = (unsigned char)st.map;
    out[3] = (unsigned char)(st.map >> 8);
    out[4] = (unsigned char)st.lost;
    out[5] = (unsigned char)(st.lost >> 8);
    out[6] = st.meets;
    out[7] = st.flags;
    memcpy(out + 8, st.crystals, DEF_SUPER_COUNT);
}

void def_super_reset(void) {
    memset(&st, 0, sizeof(st));
    st.active = -1;
    memset(&run, 0, sizeof(run));
}

void def_super_record_read(const unsigned char *in) {
    int i;

    def_super_reset();
    if (in == NULL) {
        return;
    }
    st.active = (signed char)(in[0] >= 1 && in[0] <= DEF_SUPER_COUNT ? in[0] - 1 : -1);
    st.done = in[1] > DEF_SUPER_COUNT ? DEF_SUPER_COUNT : in[1];
    st.map = (unsigned short)(in[2] | in[3] << 8);
    st.lost = (unsigned short)(in[4] | in[5] << 8);
    st.meets = in[6] > DEF_SUPER_MEETS_CAP ? DEF_SUPER_MEETS_CAP : in[6];
    st.flags = in[7];
    for (i = 0; i < DEF_SUPER_COUNT; i++) {
        st.crystals[i] = in[8 + i] > DEF_SUPER_CRYSTAL_CAP ? DEF_SUPER_CRYSTAL_CAP : in[8 + i];
    }
    if (st.active >= 0 && (st.lost >= def_super_rares[st.active].hp || !hunt_map(st.active, st.map))) {
        st.lost = 0; /* a record from another table: the target heals and moves */
        st.map = (unsigned short)draw_map(st.active, -1, -1);
    }
}

void def_super_savestate(struct PortState *s) {
    PORT_STATE_VAR(s, st);
    PORT_STATE_VAR(s, run);
}
